func (q *Queries) ListLinePrefixes(ctx context.Context, companyID string) ([]LinePrefix, error) {
	rows, err := q.db.Query(ctx, listLinePrefixes, companyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LinePrefix
	for rows.Next() {
		var i LinePrefix
		if err := rows.Scan(&i.CompanyID, &i.Prefix, &i.LineID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

