const upsertBlock = `-- name: UpsertBlock :one
INSERT INTO block_list (company_id, id, kind, value, reason, active, created_by, created_at)
VALUES ($1, $2, $3, $4, $5, true, $6, $7)
ON CONFLICT (company_id, kind, value) DO UPDATE SET reason = EXCLUDED.reason, active = true
RETURNING id
`

type UpsertBlockParams struct {
	CompanyID string
	ID        string
	Kind      string
	Value     string
	Reason    string
	CreatedBy string
	CreatedAt time.Time
}

func (q *Queries) UpsertBlock(ctx context.Context, arg UpsertBlockParams) (string, error) {
	row := q.db.QueryRow(ctx, upsertBlock,
		arg.CompanyID,
		arg.ID,
		arg.Kind,
		arg.Value,
		arg.Reason,
		arg.CreatedBy,
		arg.CreatedAt,
	)
	var id string
	err := row.Scan(&id)
	return id, err
}

